package com.capacitix.repository; import com.capacitix.entity.EmployeeTrainingProgress; import com.capacitix.entity.LearningPathItem; import com.capacitix.entity.User; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.stereotype.Repository; import java.util.Collection; import java.util.List; import java.util.Optional; @Repository public interface EmployeeTrainingProgressRepository extends JpaRepository<EmployeeTrainingProgress, Long> { /** * Find progress for a specific employee and * learning path item. */ Optional<EmployeeTrainingProgress> findByEmployeeAndLearningPathItem( User employee, LearningPathItem learningPathItem ); /** * Find all training progress records for an employee. */ List<EmployeeTrainingProgress> findByEmployee( User employee ); /** * Find all progress records for a learning path item. */ List<EmployeeTrainingProgress> findByLearningPathItem( LearningPathItem learningPathItem ); /** * Find all progress records of an employee * having a particular status. */ List<EmployeeTrainingProgress> findByEmployeeAndStatus( User employee, EmployeeTrainingProgress.TrainingStatus status ); /** * Find completed training modules for an employee. */ List<EmployeeTrainingProgress> findByEmployeeAndStatusOrderByCompletedAtDesc( User employee, EmployeeTrainingProgress.TrainingStatus status ); /** * Find progress records for multiple learning path items * at once. * * This helps avoid N+1 database queries when calculating * overall employee training progress. */ List<EmployeeTrainingProgress> findByEmployeeAndLearningPathItemIn( User employee, Collection<LearningPathItem> learningPathItems ); /** * Check whether progress already exists for * an employee and learning path item. */ boolean existsByEmployeeAndLearningPathItem( User employee, LearningPathItem learningPathItem ); /** * Count total training progress records assigned * to an employee. */ long countByEmployee( User employee ); /** * Count completed training progress records * for an employee. */ long countByEmployeeAndStatus( User employee, EmployeeTrainingProgress.TrainingStatus status ); /** * Delete all training progress records of an employee. */ void deleteByEmployee( User employee ); /** * Delete progress associated with a learning path item. */ void deleteByLearningPathItem( LearningPathItem learningPathItem ); }